fn is_smaller(arr1: &Vec<i32>, arr2: &Vec<i32>) -> bool {
    // Since it's assumed that arr1.len() == arr2.len(), we can zip them directly.
    // The iterator `.all(...)` returns true for the empty iterator, which
    // covers the case of empty arrays as required.
    arr1.iter()
        .zip(arr2.iter())
        .all(|(a, b)| a > b)
}

